sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var projectGr = new GlideRecord(WPConstants.TABLES.PROJECT);
    if (!gs.nil(current.getValue(WPConstants.WORKPLACE_PROJECT.TASK_PROJECT)) && projectGr.get(current.getValue(WPConstants.WORKPLACE_PROJECT.TASK_PROJECT))) {
        if (!projectGr.active) {
            var msg = gs.getMessage('Cannot add as the selected project is currently inactive');
            gs.addErrorMessage(msg);
            current.setAbortAction(true);
        }
    } else if (gs.nil(current.getValue(WPConstants.WORKPLACE_PROJECT.TASK_PROJECT)) && projectGr.get(previous.getValue(WPConstants.WORKPLACE_PROJECT.TASK_PROJECT))) {
        if (!projectGr.active) {
            msg = gs.getMessage('Cannot remove as the selected project is currently inactive');
            gs.addErrorMessage(msg);
            current.setAbortAction(true);
        }
    }

})(current, previous);
